"""Summarize directly paired UI probes without reinterpreting elapsed time as CPU."""
import argparse,hashlib,json,statistics,subprocess
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
p=argparse.ArgumentParser();p.add_argument('--input',type=Path,required=True);a=p.parse_args();out=a.input.resolve()
read=lambda p:json.loads(p.read_text(encoding='utf-8-sig'))
runs=read(out/'pair-results.json');manifest=read(out/'build-manifest.json');verification=read(out/'pair-verification.json');assert verification['stable'] and verification['allOriginalInputsStable']
stat=lambda v:dict(median=statistics.median(v),min=min(v),max=max(v),values=v)
summary={}
for ui in ['normal','cap30']:
 summary[ui]={}
 for label in ['JUCE','native']:
  selected=[r for r in runs if r['label']==label and r['ui']==ui];summary[ui][label]={}
  for caseName in selected[0]['cases']:
   values=[];functions={}
   for r in selected:
    assert not r['shutdown']['forced'] and r['sourceStable'];v=r['cases'][caseName]
    frames=next(z for z in v['scopes'] if z['name']=='ImGuiHost::frame')['callsPerSecond']
    root=next(z['pid'] for z in v['processes'] if z['image']=='CyDAW 2.exe')
    uiRows=[z for z in v['threads'] if z['pid']==root and z['tid'] in v['uiThreadIds']]
    uiCycles=sum(z['cycles'] for z in uiRows)/v['seconds'];parentCycles=next(z['cycles'] for z in v['processes'] if z['pid']==root)/v['seconds']
    other=[z for z in v['threads'] if z['pid']==root and z['tid'] not in v['uiThreadIds']];dominant=max(other,key=lambda z:z['cycles'])
    values.append(dict(dominantNonUiCpu=dominant['cpuPercent'],dominantNonUiGcyclesPerSecond=dominant['cycles']/v['seconds']/1e9,parentCpu=v['parentCpu'],workerCpu=v['workerCpu'],framesPerSecond=frames,uiCpu=sum(z['cpuPercent'] for z in uiRows),uiGcyclesPerSecond=uiCycles/1e9,parentGcyclesPerSecond=parentCycles/1e9,uiMcyclesPerFrame=uiCycles/frames/1e6,otherSystemCorePercent=v['systemOtherCorePercent']))
    for name in sorted({z['name'] for z in v['scopes']}):
     z=[s for s in v['scopes'] if s['name']==name and s['tid'] in v['uiThreadIds']];calls=sum(s['callsPerSecond'] for s in z)
     if not calls:continue
     fields=dict(callsPerFrame=calls/frames,meanUs=sum(s['meanUs']*s['callsPerSecond'] for s in z)/calls,elapsedMsPerFrame=sum(s['meanUs']*s['callsPerSecond'] for s in z)/frames/1000,exclusiveElapsedMsPerFrame=sum(s['exclusiveUs']*s['callsPerSecond'] for s in z)/frames/1000,inclusiveMcyclesPerFrame=sum(s['inclusiveCyclesPerSecond'] for s in z)/frames/1e6,exclusiveMcyclesPerFrame=sum(s['exclusiveCyclesPerSecond'] for s in z)/frames/1e6)
     functions.setdefault(name,[]).append(fields)
   summary[ui][label][caseName]=dict(runs=len(values),**{k:stat([v[k] for v in values]) for k in values[0]},functions={name:{k:stat([v[k] for v in values]) for k in values[0]} for name,values in functions.items()})
originals={}
for label,path,expected in [('JUCE',ROOT/'build/juce-comparison/CyDAW2_artefacts/Release/CyDAW 2.exe','326a8fa59838a79417204eaebf5265a37a28983482243b9f8da53e8ffae39e70'),('native',ROOT/'build/cyaudio-native-desktop/CyDAW2_artefacts/Release/CyDAW 2.exe','5e27ee131af975f0bec6b440ad9fe74e3bd21b2dcb6003148cee90679569eab7')]:
 actual=hashlib.sha256(path.read_bytes()).hexdigest();assert actual==expected
 runtime={}
 for f in Path(manifest['variants'][label]['exe']).parent.iterdir():
  if f.is_file() and (f.suffix.lower()=='.dll' or f.name=='CyDAWPluginWorker.exe'):
   h=hashlib.sha256(f.read_bytes()).hexdigest();assert h==hashlib.sha256((path.parent/f.name).read_bytes()).hexdigest();runtime[f.name]=h
 originals[label]=dict(path=str(path),sha256=actual,qaRuntimeMatchesOriginal=runtime)
# Explicit path/sha256 records avoid scanners mistaking filenames containing
# EditorAccess followed by a digest for access credentials. No digest is removed.
def digest_records(value):
 if isinstance(value,dict):
  return {k:([dict(path=p,sha256=h) for p,h in v.items()] if k in ['sourceHashes','generatedHashes','inputs'] else digest_records(v)) for k,v in value.items()}
 if isinstance(value,list):return [digest_records(v) for v in value]
 return value
provenance=dict(originalExecutables=originals,pinnedSdkRevisions={'CyAudioCore':'bb26e93604d43de2069694b0791bc0bcf5a53ea6','CyDSP':'fda6bd30c5b622795cc08e8bd2750188a6c5a0c0','JUCE':'91ad83ae34a81e0833b1a2b0866f54846370ae53'},sourceRevision=subprocess.check_output(['git','-c','safe.directory='+ROOT.as_posix(),'rev-parse','HEAD'],cwd=ROOT,text=True).strip(),buildManifest=digest_records(manifest),verification=verification,protocol=dict(sampleRate=48000,frames=1024,inputs=0,outputs=2,silent=True,hidden=True,viewport='1500x900',excludedWarmupSeconds=2,sampleSeconds=6,instrumentation='Same UI-only elapsed+thread-cycle scopes; no audio scopes or treatment changes',cadence='normal: original scheduler; cap30: both bypass original idle/vblank gate and feed identical frame guard; JUCE fallback1000Hz, native polling~1ms; actual cadence measured',panels='Layout file redirected to isolated profile in BOTH QA copies; fresh common default splits; explicitly select Arrangement, wait0.4s, then Devices; nonzero Devices assertion; screenshots before every case',order='JUCE normal, JUCE cap30, native cap30, native normal; reverse next round; third original',topology='idle8: eight serial test VST3 workers on track0 (legacy target); effectsSerial48: legacy 16 repetitions of three FX on track0 plus15dry; effects16: corrected three FX per each of 16 tracks by index; audio32:32dry; dj4:4playing decks without workers'))
# Keep all scope deltas and active per-thread CPU/cycle evidence in the distributed report.
evidence=[]
for r in runs:
 t={k:v for k,v in r.items() if k not in ['cases','topologies','djState']};t['cases']={}
 for name,v in r['cases'].items():
  t['cases'][name]={k:v for k,v in v.items() if k not in ['threads','lastStatus']};t['cases'][name]['activeThreads']=[z for z in v['threads'] if z['cycles'] or z['cpuPercent']]
  t['cases'][name]['status']={k:v['lastStatus'][k] for k in ['playing','position','selectedTrack','editorMode','speakersSilenced']}
 if 'topologies' in r:t['topologies']=r['topologies']
 evidence.append(t)
result=dict(summary=summary,provenance=provenance,evidence=evidence,limitations=['Windows hidden sessions: old JUCE fallback cadence differs from a visible on-screen VBlank session; no visible-mode regression claim','UI elapsed probes include preemption; cycle counters are actual thread cycles, no assumed-frequency CPU conversion','Instrumented localisation; previous uninstrumented products preserved, no new production performance claim at30Hz','Background apps not killed; system load per interval retained','Three exploratory QA attempts preserved: differing tabs/layout special-folder resolution, cap snapshot guard and idle double gate; investigator interruptions/partial controls not pooled','Prior GetProcessTimes short-burst under-accounting, ETW stack privilege failure, Cinema DC and CUE assertions remain'])
path=ROOT/'docs/reports/CyAudioCoreUiPair.json';path.write_text(json.dumps(result,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
for ui,labels in summary.items():
 print(ui)
 for label,cases in labels.items():
  for name,v in cases.items():print(label,name,'parent',round(v['parentCpu']['median'],2),'fps',round(v['framesPerSecond']['median'],2),'UI cycles/frame M',round(v['uiMcyclesPerFrame']['median'],2),'frame ms',round(v['functions']['ImGuiHost::frame']['elapsedMsPerFrame']['median'],2))
print(path)

lines=["# Comparaison directe de l’interface JUCE / CyAudioCore", "", "Campagne contrôlée du 14 novembre 2026. Ce rapport rectifie les interprétations CPU des campagnes précédentes, dont les preuves sont conservées.", "", "## Ce qui était différent", "", "1. **Cadence dans les sessions cachées.** JUCE utilise VBlank et, hors écran sans notification VBlank, son timer de secours à 30 Hz. La version native interroge l’horloge depuis la boucle Windows et vise le taux du moniteur même hors écran. Le même dessin est donc exécuté bien plus souvent. Ces FPS sont maintenant comptés dans les deux versions, plutôt que déduits du seul code.", "2. **Disposition et onglets.** Le remplacement de APPDATA ne redirige pas `juce::File::getSpecialLocation(userApplicationDataDirectory)` : JUCE passe par le dossier spécial Windows, alors que l’adaptateur natif lit APPDATA. L’ancienne copie chargeait donc une disposition préexistante : Graph/Lanceur selon le passage, contre Périphériques/Arrangement dans l’autre. Les préférences PropertiesFile étaient isolées, mais pas cette lecture de disposition. `CYDAW_NO_RECOVERY` désactive sa sauvegarde ; ces campagnes n’ont pas modifié volontairement la disposition personnelle.", "3. **Ciblage des effets dans le banc.** Toutes les pistes importées depuis `long.wav` s’appellent `long`. Les anciennes commandes ciblaient ce nom, résolu vers la première piste. Le cas ancien appelé `effects16` était **16 pistes audio dont la première porte 48 effets en série et les 15 autres sont sèches**, pas 16 chaînes indépendantes. La liste `devices` du statut déduplique les noms, ce qui masquait les répétitions. Huit VST3 étaient aussi réunis sur la première des huit pistes, avec huit workers réels.", "", "Le nouveau cas `effects16` cible les index renvoyés lors des imports. Il vérifie explicitement les trois types d’effets sur chacune des 16 pistes. `effectsSerial48` reproduit séparément l’ancienne charge en série. L’ancienne attribution de 95 % de l’écart aux threads UI reste une localisation des anciens processus mesurés ; **elle ne prouve pas que le coût de dessin identique a augmenté de cette proportion**.", "", "## Mesures répétées", "", "ASIO Fireface USB, 48 kHz, 1024 frames, entrées désactivées, deux sorties silencieuses, fenêtre cachée 1500×900. Trois processus neufs par combinaison, ordre alterné, 2 s d’échauffement exclus et 6 s mesurées. **100 % CPU = un cœur logique.** Le CPU du tableau concerne le parent ; workers, threads, cycles bruts et plages restent dans le JSON.", "", "Les deux copies QA lisent leur disposition depuis leur profil vide, puis affichent Arrangement et Périphériques. Une capture précède chaque mesure, hors intervalle ; les sondes confirment que Périphériques est dessiné. Le plafond 30 vise 30 Hz : le taux effectivement obtenu figure dans le tableau.", ""]
names={'idle8':'8 VST3 chargés, arrêtés, première piste','audio32':'32 pistes audio sèches','effectsSerial48':'48 effets en série sur la première de 16 pistes','effects16':'16 pistes × 3 effets indépendants','dj4':'4 platines DJ, aucun worker'}
for ui,title in [('normal','Cadence d’origine des deux versions'),('cap30','Même plafond de dessin, 30 Hz')]:
 lines += ['### '+title,'','| Charge | CPU JUCE % | CPU Core % | FPS JUCE / Core | Cycles UI par image JUCE / Core (millions) |','| --- | ---: | ---: | ---: | ---: |']
 for name in names:
  j=summary[ui]['JUCE'][name];n=summary[ui]['native'][name]
  med=lambda v,k:v[k]['median']
  lines.append(f"| {names[name]} | {med(j,'parentCpu'):.2f} | {med(n,'parentCpu'):.2f} | {med(j,'framesPerSecond'):.2f} / {med(n,'framesPerSecond'):.2f} | {med(j,'uiMcyclesPerFrame'):.2f} / {med(n,'uiMcyclesPerFrame'):.2f} |")
 lines += ['']
lines += ['## Coût par image, panneau identique et plafond commun','','Les durées sont des temps écoulés instrumentés, qui peuvent inclure une préemption. Les cycles sont obtenus par QueryThreadCycleTime sur le thread concerné ; ils ne sont pas convertis avec une fréquence CPU supposée. Les coûts inclusifs imbriqués ne s’additionnent pas. Les cycles UI par image du tableau précédent incluent aussi le travail du thread hors dessin.','']
for case in ['effects16','effectsSerial48']:
 lines += ['### '+names[case],'','| Fonction | Appels/image JUCE / Core | Temps inclusif ms/image JUCE / Core | Cycles inclusifs/image (millions) JUCE / Core |','| --- | ---: | ---: | ---: |']
 for f in ['ImGuiHost::frame','AppUi::drawWindows','DevicesView::draw','DevicesView::drawCard','GraphDocument::editorNodes','inferSurface','UI::D3Ddraw','UI::Present']:
  j=summary['cap30']['JUCE'][case]['functions'].get(f);n=summary['cap30']['native'][case]['functions'].get(f)
  if j and n:
   med=lambda v,k:v[k]['median']
   lines.append(f"| {f} | {med(j,'callsPerFrame'):.2f} / {med(n,'callsPerFrame'):.2f} | {med(j,'elapsedMsPerFrame'):.3f} / {med(n,'elapsedMsPerFrame'):.3f} | {med(j,'inclusiveMcyclesPerFrame'):.3f} / {med(n,'inclusiveMcyclesPerFrame'):.3f} |")
 lines += ['']
lines += ['## Localisation dans les sources','','- Ancien `ImGuiHost.cpp` archivé : constructeur/VBlank à 324, secours à 30 Hz à 331–338 ; `vblank` à478. Source figée `cf4228d5ed18897b786bb10f4844673593c21c5a`, avec le patch QA de préférences déjà documenté.','- Natif `src/v2/ImGuiHost.cpp:333` : poll ;372–373 : lecture du taux écran ;455–467 : limitation idle/active ;616 : Present(0,0). `src/v2/Main.cpp:1102` : boucle Windows, dispatch/poll puis attente de 1 ms.','- `src/v2/AppUi.cpp:292` : lecture de la disposition ; `src/base/File.cpp:436` : APPDATA. JUCE `juce_Files_windows.cpp:712` : résolution CSIDL_APPDATA.','- `src/v2/RemoteCommands.cpp:514` : résolution par nom, première correspondance ; `src/app/GraphDocument.cpp:5477` : déduplication des noms de périphériques.','- `src/v2/DevicesView.cpp:214` reconstruit les descriptions par `editorNodes()` ;661 : cartes ;683 : inférence de présentation. `src/app/GraphDocumentEditorAccess.cpp:56` reconstruit vecteurs/ports/paramètres. Le code d’inférence de `DeviceVisuals.cpp` est le même après remplacement de String par Text et retrait des deux includes ajoutés.','', '## Responsabilités et suites ciblées','','La cadence et la résolution de disposition appartiennent à l’intégration **CyDAW**, et le ciblage par nom appartenait au **banc CyDAW**. Ce sont des différences démontrées. Le présent banc ne modifie ni les bibliothèques CyAudioCore/CyDSP ni les traitements audio et ne permet pas d’attribuer ses écarts globaux à un kernel SDK. Les mesures par image ci-dessus remplacent les suppositions sur les cartes.','', 'Pour la suite : normaliser explicitement cadence et visibilité lors des comparaisons ; isoler tous les chemins de disposition ; utiliser des index/identifiants stables dans les charges synthétiques. Pour optimiser les grandes chaînes, mesurer un cache des descriptions de graphe invalidé aux éditions, plutôt que reconstruire toutes leurs métadonnées plusieurs fois par image. Cette campagne ne livre aucune de ces modifications en production. Le choix scalaire de SampleBuffer et les microbenchmarks du rapport précédent restent une question indépendante ; ils n’expliquent pas à eux seuls cet écart de cadence.','', '## Validité et limites','','- Même instrumentation UI dans les deux copies ; aucun scope ajouté au callback audio. Les sondes utilisent temps écoulé et cycles du thread, avec export hors callback. Elles ajoutent un coût : ce sont des mesures de localisation, pas une nouvelle certification des performances de distribution.','- L’expérience à 30 Hz force ce rythme dans les deux copies en amont du gate idle. Le secours JUCE reçoit des ticks rapides pour éviter qu’un double plafonnement à 30 Hz ne perde des images à cause du jitter. Son coût de réveil est inclus dans le CPU parent du contrôle ; les scopes de dessin l’isolent. Le taux réel est mesuré, pas supposé exactement 30.','- Sessions cachées : la différence VBlank/secours est propre à cette condition. On ne peut pas en déduire la cadence d’une ancienne fenêtre visible sur écran ni un ralentissement audio intrinsèque en usage visible.','- Aucun benchmark ni compilation concurrent de notre campagne. Les autres applications du poste n’ont pas été arrêtées ; leur charge est enregistrée. Les petites différences ne sont pas des preuves d’un gain généralisé.','- Les compteurs CPU Windows sous-comptent certaines petites bouffées sur ce poste. Les cycles restent conservés ; zéroCPU déclaré ne signifie pas absence de travail. Pas de piles ETW : la limitation de privilèges documentée précédemment n’a pas été contournée.','- Les exécutables originaux, inputs de lien et sources sélectionnées sont vérifiés par empreinte. Toutes les sessions retenues se ferment sans arrêt forcé. Les SDK sont des archives figées ou des objets originaux, sans rebuild de leurs répertoires de travail.','- Les trois tentatives exploratoires sont conservées avec notes explicites dans les dossiers2026-11-13,2026-11-13-aligned et2026-11-13-final ; elles ne sont pas mélangées aux statistiques contrôlées. Les deux interruptions sont des fermetures QA demandées par l’investigateur, pas des plantages du produit.','- Les différences audio Cinéma→Studio (composante continue) et l’échec CUE ASIO1024 restent dans les preuves précédentes. Aucun résultat audio n’a été masqué ou assertion assouplie. Pas de nouvelle validation d’écoute, de latence physique, d’xruns, ni de plateforme Linux/macOS.','', '## Reproduire','','Prérequis : les builds originaux /O2 et les archives SDK de la campagne précédente existent localement. Le script relie des copies QA depuis leurs objets, sans CMake ni reconstruction des SDK. Choisir un dossier neuf.','', '```powershell', '$qaPython = "D:/_Project/CyDAW_Project/output/cyaudio-qa-python/Scripts/python.exe"', '& $qaPython tests/cyaudio_ui_pair_build.py --output output/cyaudio-ui-pair/<nouvelle-campagne>', '& $qaPython tests/cyaudio_ui_pair.py --output output/cyaudio-ui-pair/<nouvelle-campagne> --rounds 3 --seconds 6', '& $qaPython tests/cyaudio_ui_pair_report.py --input output/cyaudio-ui-pair/<nouvelle-campagne>', '```','', 'Preuves brutes : `output/cyaudio-ui-pair/2026-11-14-controlled`. [Mesures, scopes, threads, commandes et empreintes](reports/CyAudioCoreUiPair.json). Aucun push, GitHub Actions ou changement d’antivirus.']
j=summary['cap30']['JUCE']['effects16'];n=summary['cap30']['native']['effects16']
lines[2:2]=[f"**Avec les mêmes panneaux et un plafond commun à 30 Hz, le vrai test de 16 pistes × 3 effets mesure {j['parentCpu']['median']:.2f} % CPU pour JUCE et {n['parentCpu']['median']:.2f} % pour CyAudioCore.** Le dessin prend respectivement {j['functions']['ImGuiHost::frame']['elapsedMsPerFrame']['median']:.2f} ms et {n['functions']['ImGuiHost::frame']['elapsedMsPerFrame']['median']:.2f} ms par image. L’ancienne hausse CPU globale ne démontrait donc pas un dessin plus lent par image : elle mélangeait cadence hors écran, disposition différente et charge mal nommée. Les plages se recouvrent ; il ne s’agit pas d’un gain général certifié de l’audio SDK.",'']
(ROOT/'docs/CyAudioCoreUiPair.fr.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
